(function ($) {
  'use strict';

  function sectionOffset() {
    return window.matchMedia('(min-width: 992px)').matches ? 0 : 64;
  }

  // Delegate because React renders the navigation after this script loads.
  $(document).on('click', 'a.js-scroll-trigger[href*="#"]', function (event) {
    if (this.hostname !== location.hostname || this.pathname !== location.pathname) return;
    var target = document.getElementById(this.hash.slice(1));
    if (!target) return;

    event.preventDefault();
    $('.navbar-collapse').collapse('hide');
    var duration = window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 0 : 250;
    $('html, body').stop().animate({
      scrollTop: Math.max(0, $(target).offset().top - sectionOffset())
    }, duration);
    history.replaceState(null, '', this.hash);
  });

  $(window).on('load', function () {
    $('body').scrollspy({ target: '#sideNav', offset: 80 });
    $('body').scrollspy('refresh');
    var target = document.getElementById(location.hash.slice(1));
    if (target) window.scrollTo(0, Math.max(0, $(target).offset().top - sectionOffset()));
  });
})(jQuery);
